function mouse_move_f495627009642515c8554f275c4c0e3fbe77b1b00793d9b25ffa959a2d3bd006097d074c1837e467689237718da0c7ed4652572b6feaf709a72244ec900e8a94(evt) {
    if (evt.buttons > 0) {
          var root = document.getElementById('f495627009642515c8554f275c4c0e3fbe77b1b00793d9b25ffa959a2d3bd006097d074c1837e467689237718da0c7ed4652572b6feaf709a72244ec900e8a94');
          root.pauseAnimations();
          var new_time = 3 * evt.layerX / evt.target.getBBox().width;
          root.setCurrentTime(new_time);
    }
}
function on_click_f495627009642515c8554f275c4c0e3fbe77b1b00793d9b25ffa959a2d3bd006097d074c1837e467689237718da0c7ed4652572b6feaf709a72244ec900e8a94(evt) {
